import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def flows(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor([[[0.2]], [[-0.1]]])
    valid = torch.ones(1, 1)
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets), "valid": synth.Tensor(valid)}
class FlowPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        flow = self.network(inputs).reshape(-1, 2, 1, 1)
        return {"predictions": [flow, flow * 0.5]}
ds = synth.Spec("raft-flow", generator=flows, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
trainer = Trainer(FlowPredictor(), train, recipe="structured-objective", recipe_config={"loss": "raft-epe", "loss_kwargs": {"gamma": 0.8, "max_flow": 400}, "bindings": {"logits_or_prediction": {"output": "predictions"}, "targets": {"batch": "targets"}, "valid": {"batch": "valid"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
